{
  "probability": 0.06,
  "range_low": 0.04,
  "range_high": 0.08,
  "summary": [
    "Anchored in the reference-class probability of a two-thirds majority (about 0.25) before current polling.",
    "Downward updates from the electoral system bias and fragmentation reduce likelihood below 10%.",
    "Opposition consolidation and limited market signals provide modest upward pressure, not enough to reverse the overall trend.",
    "Most credible polls do not show a stable path to 133+ seats for any single coalition, making a 2/3 majority unlikely.",
    "Final calibrated probability is 6% with a broad uncertainty band reflecting turnout and alliance dynamics."
  ],
  "confidence": "low",
  "narrative": "Starting from a historically motivated anchor around 25% for a 2/3 majority, structural bias, fragmentation, and uncertain polls pull the probability down. Only modest upside from opposition unity and market expectations keeps it above zero, yielding a low-probability scenario (~6%) subject to turnout and coalition dynamics.",
  "justification": {
    "anchor": {
      "probability": 0.25,
      "basis": "Two-thirds majority in Hungary's National Assembly under post-2010 reform is historically rare; this reference class provides a conservative baseline for the probability before considering 2026-specific factors."
    },
    "factor_updates": [
      {
        "factor": "Electoral-system structural bias toward the largest bloc",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Hungary's 106 single-member districts plus winner-compensation often translates votes into outsized seat advantages for the leading bloc, limiting the chance of 133+ seats for a multi-party coalition."
      },
      {
        "factor": "Opposition consolidation around TISZA",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Early-2026 polling shows TISZA leading or narrowing gaps, increasing potential anti-Orbán seat totals and some upside to crossing 133 if gains translate at district level."
      },
      {
        "factor": "Divergent polls with no clear consensus",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Polls vary by firm/methodology; lack of convergence lowers confidence in a stable path to 133 seats."
      },
      {
        "factor": "Fragmentation risk from minor parties",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Small parties near threshold can absorb votes or alter seat allocation, reducing chances of a large bloc achieving 133 seats."
      },
      {
        "factor": "Market expectations of regime change",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Forint rally signaling policy-change expectations reflects sentiment but is not binding on actual election outcomes."
      },
      {
        "factor": "Historical precedent of 2/3 majorities with broad support",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Past episodes show 2/3 can occur, albeit under broad cross-partisan backing; this provides an optimistic counterweight to structural bias."
      }
    ],
    "synthesis_rationale": "I started from a relatively high anchor for a 2/3 majority, then applied strong downward pressure from the structural-majority bias and fragmentation, with smaller upward nudges from opposition unity, market sentiment, and historical precedent. The net effect yields a low posterior probability (6%), with a wide uncertainty band; calibration accounts for the wide variance across polls and potential turnout effects."
  }
}

{
  "probability": 0.06,
  "range_low": 0.04,
  "range_high": 0.10,
  "summary": [
    "Posterior probability of any party or coalition achieving a 2/3 majority in 2026 Hungary is very low (about 6%).",
    "Initial anchor around 28% reflects a baseline reference class with historical sensitivity to turnout and cross-party cohesion, before applying updates.",
    "Updates point to modest upward pressure from opposition consolidation and market-change expectations, but are strongly offset by structural advantages for the largest bloc and the incumbent base.",
    "Overall, outcome remains highly scenario-dependent, with turnout and translation of polls to seats being the critical determinants."
  ],
  "confidence": "low",
  "narrative": "Starting from a conservatively broad anchor for a 2/3 outcome, a set of opposing updates (opposition unity, market signals, anti-war momentum) are outweighed by the electoral-system bias and Fidesz’s base, yielding a very low posterior probability. The estimate remains uncertain and highly turnout- and translation-driven."
  ,
  "justification": {
    "anchor": {
      "probability": 0.28,
      "basis": "Two-thirds majority (133+ seats) in Hungary's 199-seat National Assembly is historically challenging under the post-2010 reform, with the reference class defined as elections with 133+ seats as the 2/3 threshold; anchor reflects baseline plausibility before updates."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation around TISZA and favorable polling",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Polls in early 2026 show TISZA leading or narrowing the gap, suggesting potential gains for an anti-Orbán bloc; however, these gains are contingent on turnout and coalition coherence."
      },
      {
        "factor": "Fidesz-KDNP incumbent base and turnout advantage",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Long-standing organizational strength and base support continue to dampen the chance of a 2/3 majority for any coalition opposing Fidesz."
      },
      {
        "factor": "Electoral-system bias toward the largest bloc",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Winner-compensation in Hungary's mixed system tends to amplify the leading bloc’s seat share, making a 133-seat outcome harder for a multi-party coalition."
      },
      {
        "factor": "Market expectations of regime change",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Forint rally signals potential policy change if the opposition wins, providing a marginal booster to anti-incumbent odds but not determining results."
      },
      {
        "factor": "Historical precedent of 2/3 majorities with broad support",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Past 2/3 outcomes occurred when broad cross-party backing existed; this remains a rare and contingent path."
      },
      {
        "factor": "Opposition anti-war campaigning and momentum behind TISZA",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Momentum around anti-war messaging could broaden turnout and appeal, contributing to potential seat gains for the anti-Orbán bloc."
      }
    ],
    "synthesis_rationale": "The anchor of 0.28 was adjusted downward by structural and base advantages favoring the largest bloc, with upward adjustments from opposition consolidation, market signals, and momentum. The net effect, given Hungary’s electoral structure and recent polling dispersion, yields a calibrated posterior near 0.06, with a wide uncertainty range reflecting turnout sensitivity and potential fragmentation. Calibration accounts for historical rarity of 2/3 outcomes and the difficulty of converting polls into proportional seat gains."
  }
}

